    /** One path of a glyph, with the SVG's transform: translation, then optional mirror or quarter turn. */
    private class P(
        val dx: Float,
        val dy: Float,
        val d: String,
        val rotate: Float = 0f,
        val flip: Boolean = false,
        val evenOdd: Boolean = true,
    )

    private fun glyph(name: String, vararg paths: P): ImageVector {
        val b = ImageVector.Builder(name, 16.dp, 16.dp, 16f, 16f)
        for (p in paths) {
            b.addGroup(rotate = p.rotate, scaleX = if (p.flip) -1f else 1f, translationX = p.dx, translationY = p.dy)
            b.addPath(
                PathParser().parsePathString(p.d).toNodes(),
                pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = SolidColor(Color.White),
            )
            b.clearGroup()
        }
        return b.build()
    }
}
